import os
import shutil

BASE_DIR = os.path.expanduser('~/flipkart-review-search-pro/python_server')
PUBLIC_DIR = os.path.join(BASE_DIR, 'public')
ADMIN_DIR = os.path.join(PUBLIC_DIR, 'admin')

os.makedirs(ADMIN_DIR, exist_ok=True)
print("[Setup] Initializing PythonAnywhere backend in", BASE_DIR)

# Copy existing server/public static files
REPO_DIR = os.path.expanduser('~/flipkart-review-search-pro')
SERVER_PUBLIC = os.path.join(REPO_DIR, 'server', 'public')

if os.path.exists(SERVER_PUBLIC):
    for item in os.listdir(SERVER_PUBLIC):
        s = os.path.join(SERVER_PUBLIC, item)
        d = os.path.join(PUBLIC_DIR, item)
        if os.path.isdir(s):
            shutil.copytree(s, d, dirs_exist_ok=True)
        else:
            shutil.copy2(s, d)
    print("-> Copied web public assets.")


# Write app.py
with open(os.path.join(BASE_DIR, "app.py"), "wb") as f:
    import base64
    f.write(base64.b64decode(""))
print("-> Created app.py")

